  async function loadProfile(){if(!db||!user)return;let {data,error}=await db.from('confam_profiles').select('*').eq('id',user.id).maybeSingle();if(error){console.error(error);return}if(!data){const base=(user.email?.split('@')[0]||'membre').toLowerCase().replace(/[^a-z0-9_]/g,'').slice(0,18)||'membre';const {data:created,error:e}=await db.from('confam_profiles').insert({id:user.id,display_name:base,username:base+'_'+user.id.slice(0,4),role:'music_lover'}).select().single();if(!e)data=created}profile=data;updateAccount()}
