  async function loadFeed(){if(!db){$('feed-list').innerHTML='<div class="empty-state"><div class="empty-icon">♫</div><h2>CONFAM prend vie ici.</h2><p>Pour activer les comptes, les publications et les audios, ajoute les identifiants Supabase dans <b>config.js</b>, puis exécute le fichier <b>supabase-setup.sql</b>.</p></div>';return}const {data,error}=await db.from('confam_posts').select('*, author:confam_profiles!confam_posts_user_id_fkey(id,display_name,username,role,avatar_url)').order('created_at',{ascending:false}).limit(20);if(error){$('feed-list').innerHTML=`<div class="loading-card">Impossible de charger le Feed : ${esc(error.message)}</div>`;return}posts=data||[];await renderPosts('feed-list',posts);loadSuggestions();loadStories()}
  async function loadBeats(){if(!db){$('beats-list').innerHTML='<div class="empty-state"><h2>Les beats arrivent.</h2><p>Connecte la base CONFAM pour découvrir les instrumentaux.</p></div>';return}const {data,error}=await db.from('confam_posts').select('*, author:confam_profiles!confam_posts_user_id_fkey(id,display_name,username,role,avatar_url)').eq('is_beat',true).eq('allow_participation',true).order('created_at',{ascending:false}).limit(50);if(error){$('beats-list').innerHTML='<div class="loading-card">Impossible de charger les beats : '+esc(error.message)+'</div>';return}const beats=data||[];posts=[...posts.filter(p=>!beats.some(b=>b.id===p.id)),...beats];renderPosts('beats-list',beats)}
