  function audioBufferToWav(buffer){const channels=buffer.numberOfChannels,frames=buffer.length,rate=buffer.sampleRate,bytes=44+frames*channels*2,view=new DataView(new ArrayBuffer(bytes));const w=(o,s)=>{for(let i=0;i<s.length;i++)view.setUint8(o+i,s.charCodeAt(i))};w(0,'RIFF');view.setUint32(4,bytes-8,true);w(8,'WAVE');w(12,'fmt ');view.setUint32(16,16,true);view.setUint16(20,1,true);view.setUint16(22,channels,true);view.setUint32(24,rate,true);view.setUint32(28,rate*channels*2,true);view.setUint16(32,channels*2,true);view.setUint16(34,16,true);w(36,'data');view.setUint32(40,bytes-44,true);let pos=44;for(let n=0;n<frames;n++)for(let c=0;c<channels;c++){const x=Math.max(-1,Math.min(1,buffer.getChannelData(c)[n]));view.setInt16(pos,x<0?x*32768:x*32767,true);pos+=2}return new Blob([view],{type:'audio/wav'})}
