  async function openBeatStudio(postId,url,beatName,artistName){if(!user){openAuth('login');return}closeBeatStudio();const modal=document.createElement('div');modal.id='beat-studio-modal';modal.className='modal';modal.innerHTML='<div class="modal-backdrop" data-beat-close></div><div class="modal-card beat-studio-card"><div class="modal-head"><h2>Participer au beat 🎙️</h2><button class="close-button" data-beat-close>×</button></div><p class="muted" id="beat-studio-title"></p><audio id="beat-studio-player" preload="auto"></audio><div class="beat-studio-wave"><b>♫ Instrumental original</b><small id="beat-studio-clock">Prêt</small></div><button id="beat-studio-start" class="primary-button full">● Démarrer beat + microphone</button><button id="beat-studio-stop" class="outline-button full" disabled>■ Terminer</button><p id="beat-studio-status" class="form-message">Écouteurs recommandés. La voix sera enregistrée sur le beat.</p><div id="beat-studio-preview"></div><button id="beat-studio-publish" class="primary-button full" disabled>Publier ma participation →</button></div>';document.body.appendChild(modal);const player=modal.querySelector('#beat-studio-player'),start=modal.querySelector('#beat-studio-start'),stop=modal.querySelector('#beat-studio-stop'),status=modal.querySelector('#beat-studio-status'),preview=modal.querySelector('#beat-studio-preview'),publish=modal.querySelector('#beat-studio-publish');player.src=url;modal.querySelector('#beat-studio-title').textContent='Beat de '+artistName+' · '+beatName;beatStudio={modal,player,recorder:null,stream:null,chunks:[],voiceBlob:null,previewUrl:null,postId,url,artistName,beatName,recording:false};player.addEventListener('timeupdate',()=>modal.querySelector('#beat-studio-clock').textContent=fmt(player.currentTime));player.addEventListener('ended',()=>{if(beatStudio?.recording)stopBeatRecording()});modal.querySelectorAll('[data-beat-close]').forEach(el=>el.addEventListener('click',closeBeatStudio));start.addEventListener('click',async()=>{start.disabled=true;status.textContent='Accès microphone…';try{const stream=await requestMicrophoneAccess();if(!beatStudio){stream.getTracks().forEach(t=>t.stop());return}beatStudio.stream=stream;beatStudio.chunks=[];const rec=createCompatibleRecorder(stream);beatStudio.recorder=rec;rec.ondataavailable=e=>{if(e.data?.size&&beatStudio)beatStudio.chunks.push(e.data)};rec.onstop=async()=>{if(!beatStudio)return;beatStudio.stream?.getTracks().forEach(t=>t.stop());beatStudio.stream=null;beatStudio.voiceBlob=new Blob(beatStudio.chunks,{type:rec.mimeType||'audio/webm'});beatStudio.recording=false;start.disabled=false;start.textContent='↻ Recommencer';stop.disabled=true;if(!beatStudio.voiceBlob.size){status.textContent='Aucune voix enregistrée. Réessaie.';return}status.textContent='Mixage du beat et de la voix…';try{const mix=await mixBeatTracks(beatStudio);if(!beatStudio)return;beatStudio.previewUrl=URL.createObjectURL(mix);preview.innerHTML='<audio controls src="'+beatStudio.previewUrl+'"></audio><p class="muted">Écoute ton résultat avant de publier.</p>';publish.disabled=false;status.textContent='Mix prêt !'}catch(err){if(beatStudio)status.textContent='Mixage impossible : '+err.message}};player.currentTime=0;await player.play();rec.start(200);beatStudio.recording=true;stop.disabled=false;start.textContent='Enregistrement en cours';status.textContent='● Beat en lecture · microphone actif'}catch(err){start.disabled=false;status.textContent=microphoneAccessError(err)}});stop.addEventListener('click',stopBeatRecording);publish.addEventListener('click',async()=>{if(!beatStudio?.previewUrl)return;publish.disabled=true;publish.textContent='Publication…';try{const blob=await fetch(beatStudio.previewUrl).then(r=>r.blob()),file=new File([blob],'participation-'+Date.now()+'.wav',{type:'audio/wav'}),upload=await uploadFile(file,'confam-audio'),row={user_id:user.id,content:'🎙️ Participation au beat de '+beatStudio.artistName+' — '+beatStudio.beatName,audio_url:upload.url,audio_path:upload.path,audio_name:'Participation · '+beatStudio.beatName,post_type:'beat_collab',parent_beat_id:beatStudio.postId,is_beat:false,allow_participation:false};const {error}=await db.from('confam_posts').insert(row);if(error)throw error;closeBeatStudio();await loadFeed();notify('Participation publiée !')}catch(err){status.textContent='Publication impossible : '+err.message;publish.disabled=false;publish.textContent='Réessayer →'}})}
